#!/usr/bin/env python3
"""Generate llama-spec.json"""
import json
import os

spec = {
    "version": 1,
    "source": "https://github.com/ggml-org/llama.cpp/blob/master/tools/server/README.md",
    "migrations": {
        "drop": ["spec-ngram-size-n", "spec-ngram-size-m", "spec-ngram-min-hits"],
        "rename": {
            "draft": "spec-draft-n-max", "draft-max": "spec-draft-n-max",
            "draft-n-max": "spec-draft-n-max", "draft-min": "spec-draft-n-min",
            "draft-n-min": "spec-draft-n-min", "model-draft": "spec-draft-model",
            "ctx-size-draft": "spec-draft-ctx-size", "n-gpu-layers-draft": "spec-draft-ngl",
            "gpu-layers-draft": "spec-draft-ngl", "device-draft": "spec-draft-device",
            "threads-draft": "spec-draft-threads", "threads-batch-draft": "spec-draft-threads-batch",
            "cpu-moe-draft": "spec-draft-cpu-moe", "draft-cpu-moe": "spec-draft-cpu-moe",
            "n-cpu-moe-draft": "spec-draft-n-cpu-moe",
            "override-tensor-draft": "spec-draft-override-tensor",
            "draft-p-min": "spec-draft-p-min", "draft-p-split": "spec-draft-p-split",
            "hf-repo-draft": "spec-draft-hf", "cache-type-k-draft": "spec-draft-type-k",
            "cache-type-v-draft": "spec-draft-type-v",
            "webui-config": "ui-config", "webui-config-file": "ui-config-file",
            "webui-mcp-proxy": "ui-mcp-proxy"
        }
    },
    "defaults": {"n_batch": 2048, "parallel": -1},
    "params": []
}
p = spec["params"]

def A(k, l, d, t, df, c, ty, cl, **kw):
    e = {"key": k, "label": l, "description": d, "type": t, "default": df, "category": c, "typed": ty, "cli_flag": cl}
    e.update(kw)
    p.append(e)

